function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentPredictionResults = [];

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データ読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    window.aivicApi.list(1).then(stores => {
      if (stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // 商品カテゴリ読み込み（商品マスタから重複なしで取得）
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    window.aivicApi.list(2).then(products => {
      if (products) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
        categorySelect.innerHTML = '<option value="">すべてのカテゴリ</option>';
        categories.forEach(category => {
          categorySelect.innerHTML += `<option value="${category}">${category}</option>`;
        });
      }
    });
  }

  // 商品一覧表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.id}">
        <td><input type="radio" name="selected-product" value="${product.id}" class="product-radio"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名 || ''}</td>
        <td>${product.商品カテゴリID || ''}</td>
        <td class="prediction-qty" data-product-id="${product.id}">-</td>
        <td class="prediction-accuracy" data-product-id="${product.id}">-</td>
        <td><button class="action-btn secondary select-product-btn" data-id="${product.id}">選択</button></td>
      </tr>
    `).join('');
  }

  // 商品検索
  function searchProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (products) {
        let filtered = products.filter(p => p.有効フラグ);

        if (categoryId) {
          filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
        }

        if (searchTerm) {
          filtered = filtered.filter(p => 
            (p.商品名 && p.商品名.includes(searchTerm)) ||
            (p.商品コード && p.商品コード.includes(searchTerm))
          );
        }

        renderProducts(filtered);
      }
    });
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return;
    }

    // 需要予測結果を取得
    window.aivicApi.list(8).then(predictions => {
      if (predictions) {
        currentPredictionResults = predictions.filter(p => 
          p.店舗ID === storeId &&
          p.予測対象日 >= startDate &&
          p.予測対象日<= endDate
        );

        // 予測結果を商品一覧に反映
        currentPredictionResults.forEach(pred => {
          const qtyCell = container.querySelector(`.prediction-qty[data-product-id="${pred.商品ID}"]`);
          const accCell = container.querySelector(`.prediction-accuracy[data-product-id="${pred.商品ID}"]`);
          if (qtyCell) qtyCell.textContent = pred.予測数量 || '-';
          if (accCell) accCell.textContent = pred.予測精度 ? `${pred.予測精度}%` : '-';
        });
      }
    });
  }

  // 商品選択
  function selectProduct(productId) {
    window.aivicApi.list(2).then(products => {
      if (products) {
        selectedProduct = products.find(p => p.id === productId);
        if (selectedProduct) {
          container.querySelector('#selected-product-name').textContent = 
            `選択商品: ${selectedProduct.商品名} (${selectedProduct.商品コード})`;

          // デフォルト値設定
          container.querySelector('#lead-time').value = selectedProduct.リードタイム日数 || 7;
          container.querySelector('#safety-stock').value = selectedProduct.最小発注数量 || 10;

          container.querySelector('#calculation-area').style.display = 'block';
        }
      }
    });
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // バリデーション
    if (currentStock < 0) {
      showError('在庫数は0以上の値を入力してください');
      return;
    }

    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は0以上の数値を入力してください');
      return;
    }

    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return;
    }

    if (weatherImpact < 0 || weatherImpact > 200) {
      showError('天候影響度は0-200%の範囲で入力してください');
      return;
    }

    if (eventImpact < 0 || eventImpact > 200) {
      showError('イベント影響度は0-200%の範囲で入力してください');
      return;
    }

    if (seasonalFactor < 0.1 || seasonalFactor > 10) {
      showError('季節補正係数は0.1-10の範囲で入力してください');
      return;
    }

    // 予測数量取得
    const prediction = currentPredictionResults.find(p => p.商品ID === selectedProduct.id);
    const baseDemand = prediction ? prediction.予測数量 : 0;

    // 発注量計算
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で計算
    const recommendedQty = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 結果表示
    container.querySelector('#ai-recommended-qty').textContent = recommendedQty;

    // 手動調整値がある場合は最終発注量を更新
    const manualAdjustment = parseInt(container.querySelector('#manual-adjustment').value);
    const finalQty = isNaN(manualAdjustment) ? recommendedQty : manualAdjustment;
    container.querySelector('#final-order-qty').textContent = finalQty;
  }

  // スライダー値更新
  function updateSliderValues() {
    const weatherSlider = container.querySelector('#weather-impact');
    const eventSlider = container.querySelector('#event-impact');
    const weatherValue = container.querySelector('#weather-value');
    const eventValue = container.querySelector('#event-value');

    weatherSlider.addEventListener('input', () => {
      weatherValue.textContent = `${weatherSlider.value}%`;
    });

    eventSlider.addEventListener('input', () => {
      eventValue.textContent = `${eventSlider.value}%`;
    });
  }

  // 手動調整値変更時の処理
  function handleManualAdjustment() {
    const manualInput = container.querySelector('#manual-adjustment');
    manualInput.addEventListener('input', () => {
      const value = parseInt(manualInput.value);
      if (value < 0) {
        showError('発注量は0以上の値を入力してください');
        manualInput.value = '';
        return;
      }

      const finalQty = isNaN(value) ? 
        container.querySelector('#ai-recommended-qty').textContent : value;
      container.querySelector('#final-order-qty').textContent = finalQty;
    });
  }

  // 初期化
  loadStores();
  loadCategories();
  updateSliderValues();
  handleManualAdjustment();

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択イベント
  container.addEventListener('click', (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      selectProduct(productId);

      // ラジオボタンも選択状態にする
      const radio = container.querySelector(`input[value="${productId}"]`);
      if (radio) radio.checked = true;
    }
  });

  // ラジオボタン選択時
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-radio')) {
      selectProduct(e.target.value);
    }
  });

  // 発注書作成ボタン
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const finalQty = container.querySelector('#final-order-qty').textContent;
    if (finalQty === '-' || finalQty === '0') {
      showError('発注量を計算してください');
      return;
    }

    window.showScreen('scr-1778591907544'); // 発注書作成画面
  });
}
